import re

def parse_duration(text):
    """
    Convert a duration string into whole seconds.

    The string is one or more parts of the form <non-negative integer><unit>,
    units h (hours), m (minutes), s (seconds), appearing in that order, each unit at most once, with no spaces.

    Parameters:
    text (str): The duration string to parse.

    Returns:
    int: The duration in whole seconds.

    Raises:
    ValueError: If any part is invalid (empty, unknown unit, missing number, spaces, wrong order, repeated unit).
    """
    if not text:
        raise ValueError("Input string is empty")

    # Regular expression to match the expected duration format: <non-negative integer><unit>
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, text)

    if not matches:
        raise ValueError("Invalid format")

    seconds = 0
    seen_units = set()

    for num, unit in matches:
        if unit in seen_units:
            raise ValueError("Repeated unit")
        seen_units.add(unit)

        if unit == 'h':
            seconds += int(num) * 3600
        elif unit == 'm':
            seconds += int(num) * 60
        elif unit == 's':
            seconds += int(num)

    return seconds

